import json, urllib.request, ssl, base64, datetime

ctx = ssl._create_unverified_context()
now = datetime.datetime.utcnow()

# --- Wazuh OpenSearch: last 24h alerts ---
query = {
    "size": 0,
    "track_total_hits": True,
    "query": {"bool": {"must": [{"range": {"timestamp": {"gte": "now-24h"}}}]}},
    "aggs": {
        "by_level": {
            "range": {
                "field": "rule.level",
                "ranges": [
                    {"key": "critical", "from": 12},
                    {"key": "high", "from": 8, "to": 12}
                ]
            }
        },
        "top_rule": {"terms": {"field": "rule.description", "size": 1}}
    }
}

creds = "$opensearch_user:$opensearch_pass"
auth = base64.b64encode(creds.encode()).decode()
headers = {"Content-Type": "application/json", "Authorization": f"Basic {auth}"}

try:
    req = urllib.request.Request("$opensearch_url/wazuh-alerts-4.x-*/_search",
        data=json.dumps(query).encode(), headers=headers, method="POST")
    resp = urllib.request.urlopen(req, context=ctx, timeout=15)
    data = json.loads(resp.read().decode())
    total = data["hits"]["total"]["value"]
    buckets = {b["key"]: b["doc_count"] for b in data["aggregations"]["by_level"]["buckets"]}
    crit = buckets.get("critical", 0)
    high = buckets.get("high", 0)
    top_rules = data["aggregations"]["top_rule"]["buckets"]
    top_rule = top_rules[0]["key"] if top_rules else "None"
except Exception as e:
    total, crit, high, top_rule = 0, 0, 0, f"Error: {str(e)[:80]}"

# --- TheHive: open cases ---
try:
    req2 = urllib.request.Request("$thehive_url/api/case/_search?range=0-1000",
        data=json.dumps({"query": {"_field": "status", "_value": "Open"}}).encode(),
        headers={"Content-Type": "application/json", "Authorization": "Bearer $thehive_api_key"},
        method="POST")
    resp2 = urllib.request.urlopen(req2, timeout=10)
    cases = json.loads(resp2.read().decode())
    open_cases = len(cases) if isinstance(cases, list) else 0
except Exception as e:
    open_cases = f"Error: {str(e)[:60]}"

section = f"SECURITY (last 24h)\\nAlerts: {total} ({crit} crit, {high} high)\\nOpen Cases: {open_cases}\\nTop Rule: {top_rule}"
print(json.dumps({"section": section}))

import json, urllib.request, ssl, base64

ctx = ssl._create_unverified_context()
elk_creds = "$elk_user:$elk_pass"
elk_auth = base64.b64encode(elk_creds.encode()).decode()
elk_headers = {"Content-Type": "application/json", "Authorization": f"Basic {elk_auth}"}

# ML anomalies â€” record-level results (score > 50, last 12h)
anomalies = []
try:
    q1 = {
        "size": 5,
        "query": {
            "bool": {
                "must": [
                    {"term": {"result_type": "record"}},
                    {"range": {"timestamp": {"gte": "now-12h"}}},
                    {"range": {"record_score": {"gt": 50}}}
                ]
            }
        },
        "sort": [{"record_score": "desc"}]
    }
    req1 = urllib.request.Request("$elk_url/.ml-anomalies-*/_search",
        data=json.dumps(q1).encode(), headers=elk_headers, method="POST")
    resp1 = urllib.request.urlopen(req1, context=ctx, timeout=10)
    ml_data = json.loads(resp1.read().decode())
    hits = ml_data.get("hits", {}).get("hits", [])
    for h in hits:
        src = h["_source"]
        score = src.get("record_score", 0)
        job = src.get("job_id", "?")
        func = src.get("function_description", src.get("function", "?"))
        by_val = src.get("by_field_value", "")
        part_val = src.get("partition_field_value", "")
        detail = by_val or part_val or ""
        anomalies.append(f"{job} {func}({detail}) score={score:.0f}")
except Exception as e:
    anomalies.append(f"ML query error: {str(e)[:60]}")

if not anomalies:
    anomaly_line = "No high-score anomalies (12h)"
else:
    anomaly_line = "; ".join(anomalies[:3])

# OpenCTI threat intel: new IOCs last 24h
try:
    q2 = {"size": 0, "track_total_hits": True, "query": {"range": {"@timestamp": {"gte": "now-24h"}}}}
    req2 = urllib.request.Request("$elk_url/opencti-threat-intel/_search",
        data=json.dumps(q2).encode(), headers=elk_headers, method="POST")
    resp2 = urllib.request.urlopen(req2, context=ctx, timeout=10)
    ioc_count = json.loads(resp2.read().decode())["hits"]["total"]["value"]
except:
    ioc_count = "N/A"

section = f"OVERNIGHT NOTABLE\\nML Anomalies: {anomaly_line}\\nThreat Intel IOCs (24h): {ioc_count}"
print(json.dumps({"section": section}))

import json, datetime, urllib.request, re

today = datetime.datetime.utcnow().strftime("%Y-%m-%d")

results = self.full_execution.get("results", []) if isinstance(self.full_execution, dict) else []

section_map = {}
haccp_embed = None
for r in results:
    label = r.get("action", {}).get("label", "")
    if label in ("security_data", "infra_data", "overnight_data"):
        try:
            p = json.loads(r.get("result", "{}"))
            msg = p.get("message", p) if isinstance(p, dict) else p
            if isinstance(msg, str):
                msg = json.loads(msg)
            section_map[label] = msg.get("section", str(msg))
        except:
            section_map[label] = label + ": parse error"
    elif label == "haccp_briefing":
        try:
            p = json.loads(r.get("result", "{}"))
            msg = p.get("message", p) if isinstance(p, dict) else p
            if isinstance(msg, str):
                msg = json.loads(msg)
            section_map["haccp_briefing"] = msg.get("stats_line", "HACCP: data unavailable")
            haccp_embed = msg.get("embed", None)
        except:
            section_map["haccp_briefing"] = "HACCP: parse error"

raw_sections = []
for lbl in ["security_data", "infra_data", "overnight_data"]:
    raw_sections.append(section_map.get(lbl, lbl + ": data unavailable"))

# Include haccp stats line for Ollama context (not the full summary -- that goes in the embed)
haccp_stats = section_map.get("haccp_briefing", "HACCP: data unavailable")

# Combine all section data + haccp stats for Ollama synthesis
all_data = " | ".join(raw_sections) + " | " + haccp_stats
if len(all_data) > 3000:
    all_data = all_data[:3000]

def sanitize(s):
    s = re.sub(r"<think>.*?</think>", "", s, flags=re.DOTALL)
    s = s.replace(chr(92), "").replace(chr(34), chr(39)).replace(chr(13), "").replace(chr(9), " ")
    s = "".join(c for c in s if ord(c) >= 32)
    return s.strip()

assessment = ""
try:
    prompt = "/no_think You are the SOC watch officer writing the morning briefing for a home lab SOC. Synthesize the following operational data into a concise watch turnover briefing. Structure: 1) Security posture in one sentence (alert volume, threat level, any critical/high alerts). 2) Infrastructure status in one sentence (hosts up/down, resource concerns). 3) Notable items from overnight if any. 4) Action items for incoming watch, or 'No action required -- steady state.' Do not use markdown. Plain text only. Be specific with numbers. Data: " + all_data
    payload = json.dumps({
        "model": "qwen3:8b",
        "prompt": prompt,
        "system": "You are a SOC watch officer. Write in telegraphic military style: short declarative sentences, present tense for status, past tense for events. No filler, no editorializing. Be specific about numbers and hostnames.",
        "stream": False,
        "keep_alive": "24h",
        "options": {"temperature": 0.3}
    }).encode()
    req = urllib.request.Request("$ollama_url/api/generate",
        data=payload, headers={"Content-Type": "application/json"})
    resp = urllib.request.urlopen(req, timeout=180)
    text = json.loads(resp.read().decode()).get("response", "")
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip()
    text = text.replace("\n", " ").replace("\r", "")
    if not text:
        retry_payload = json.dumps({
            "model": "qwen3:8b",
            "prompt": "/no_think " + prompt.replace("/no_think ", ""),
            "stream": False, "keep_alive": "24h",
            "options": {"temperature": 0.3}
        }).encode()
        retry_req = urllib.request.Request("$ollama_url/api/generate",
            data=retry_payload, headers={"Content-Type": "application/json"})
        retry_resp = urllib.request.urlopen(retry_req, timeout=180)
        text = json.loads(retry_resp.read().decode()).get("response", "")
        text = re.sub(r"<think>.*?</think>", "", text, flags=re.DOTALL).strip()
        text = text.replace("\n", " ").replace("\r", "")
    if text:
        assessment = sanitize(text)
    else:
        assessment = "Watch officer assessment unavailable."
except Exception as e:
    assessment = "LLM unavailable: " + str(e)[:60]

NL = chr(92) + "n"
header = "**MORNING BRIEFING -- " + today + "**"
parts = [header, "---", "__Watch Officer Assessment__", assessment, "---"]
for s in raw_sections:
    parts.append(s)
    parts.append("---")

body = NL.join(parts)
if len(body) > 1950:
    body = body[:1947] + "..."

result = {"content": body, "haccp_embed": haccp_embed}
print(json.dumps(result))
